html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
<div class="ap">
{{ ap.header(c, "ASSET ISSUE NOTE", "إذن صرف معدات", [
    ["Allocation No.", doc.name],
    ["Delivery Date", ap.date(doc.delivery_date)],
    ["Delivery / Gate Pass", doc.delivery_ref],
    ["Status", doc.status]
]) }}
{{ ap.two_boxes(
    ap.info_box("Project", [["Project", doc.project], ["Name", doc.project_name], ["Site / Location", doc.site_location], ["Division", doc.cost_center]]),
    ap.info_box("Issue", [["Total Qty", ap.num(doc.total_qty)], ["Depreciation / Day", ap.money(doc.daily_charge, doc)], ["Still on Site", ap.num(doc.on_site_qty) if doc.docstatus == 1 else ""], ["Cost to Date", ap.amt(doc.total_project_cost) if doc.docstatus == 1 else ""]])
) }}
<table class="items">
  <thead><tr><th style="width:4%">#</th><th>Asset</th><th>UOM</th><th class="right">Qty</th><th class="right">Rate / Unit / Day</th><th class="right">Per Day</th>
  {%- if doc.docstatus == 1 %}<th class="right">Returned</th><th class="right">Damaged</th><th class="right">On Site</th>{% endif %}</tr></thead>
  <tbody>
  {%- for r in doc.get("items") %}
  <tr><td>{{ loop.index }}</td><td><span class="item-name">{{ r.asset_name }}</span><div class="muted">{{ r.project_asset }}</div></td><td>{{ r.uom or "" }}</td>
    <td class="right"><b>{{ ap.num(r.qty) }}</b></td><td class="right">{{ "%.4f" | format(r.daily_rate or 0) }}</td><td class="right">{{ ap.amt(r.daily_amount) }}</td>
    {%- if doc.docstatus == 1 %}<td class="right">{{ ap.num(r.returned_qty) }}</td><td class="right">{{ ap.num(r.damaged_qty) }}</td><td class="right">{{ ap.num(r.on_site_qty) }}</td>{% endif %}</tr>
  {%- endfor %}
  <tr class="sub"><td colspan="3">Total</td><td class="right">{{ ap.num(doc.total_qty) }}</td><td></td><td class="right">{{ ap.amt(doc.daily_charge) }}</td>
    {%- if doc.docstatus == 1 %}<td colspan="2"></td><td class="right">{{ ap.num(doc.on_site_qty) }}</td>{% endif %}</tr>
  </tbody>
</table>
<p class="muted" style="margin-top:6px">Depreciation is charged to the project per unit per day from the delivery date until the assets are returned. Damaged or lost assets are charged at their book value.</p>
{{ ap.section("Remarks", doc.remarks and doc.remarks | replace("\n", "<br>")) }}
{{ ap.signatures(c, ["Issued by (Store)", "Received by (Site)", "Approved by"], 9) }}
{{ ap.footer(c) }}
</div>
